package alternate;import java.util.*;public class Huffman{private static final class Node{final String word,first;final int frequency;final Node left,right;Node(String word,int frequency){this.word=word;first=word;this.frequency=frequency;left=right=null;}Node(Node left,Node right){word=null;frequency=left.frequency+right.frequency;first=left.first.compareTo(right.first)<=0?left.first:right.first;this.left=left;this.right=right;}}public record Encoded(Map<String,Integer>frequency,Map<String,String>codes,String bits){}private static void assign(Node node,String path,Map<String,String>codes){if(node.word!=null){codes.put(node.word,path.isEmpty()?"0":path);return;}assign(node.left,path+"0",codes);assign(node.right,path+"1",codes);}public static Encoded encode(String input){List<String>words=input.trim().isEmpty()?List.of():Arrays.asList(input.trim().split(" +"));Map<String,Integer>frequency=new TreeMap<>();for(String word:words)frequency.merge(word,1,Integer::sum);Map<String,String>codes=new TreeMap<>();PriorityQueue<Node>queue=new PriorityQueue<>(Comparator.comparingInt((Node n)->n.frequency).thenComparing((Node n)->n.first,Comparator.reverseOrder()));for(var e:frequency.entrySet())queue.add(new Node(e.getKey(),e.getValue()));if(!queue.isEmpty()){while(queue.size()>1)queue.add(new Node(queue.remove(),queue.remove()));assign(queue.remove(),"",codes);}StringBuilder bits=new StringBuilder();for(String word:words)bits.append(codes.get(word));return new Encoded(frequency,codes,bits.toString());}public static void main(String[]args){Encoded result=encode("one two two three three three");for(String word:result.frequency.keySet())System.out.println(word+" — "+result.frequency.get(word)+" — "+result.codes.get(word));System.out.println(result.bits);}}
